/* ===== Dead Town · balbuceo de los aldeanos: globos de texto (y murmullo suave) solo al acercar la cámara ===== */
(function(){
'use strict';
const ZOOM=1.45,MAXB=3,pick=a=>a[Math.floor(Math.random()*a.length)];
const GEN=['Qué día más largo...','¿Has oído eso?','Todo en orden por aquí.','Menos mal que estamos juntos.','Tengo los pies hechos polvo.','Otro día más.','Hay que seguir adelante.','Este sitio ya es un hogar.','Cuidado con los pasillos oscuros.','Me gustaría un café de verdad.'];
const PRO={Agricultor:['Esta tierra aún da frutos.','La cosecha va bien.','Falta agua para los surcos.'],Cocinero:['Hoy toca guiso.','Sin sal no es lo mismo.','Huele a pan, ¿verdad?'],'Médico':['Hay que desinfectar todo.','Que nadie se infecte.','Necesito más vendas.'],Soldado:['Vigilo el perímetro.','Siguen ahí fuera.','Cargador listo.'],Constructor:['Esto aguantará.','Otra viga más.','Medir dos veces, cortar una.'],Explorador:['El mapa no miente.','Hay mucho por descubrir.','Vi huellas al norte.'],'Mecánico':['Esto necesita grasa.','Pásame la llave.','Lo arreglo en un momento.'],Recolector:['Todo sirve.','Un poco más de madera.','Aquí queda chatarra.'],'Científico':['Los datos no cuadran.','Interesante...','Hay que anotarlo.']};
const HUNGRY=['Tengo un hambre...','Mi estómago ruge.','¿Queda algo de comer?'],THIRSTY=['Qué sed tengo.','Necesito agua.'],HURT=['Me duele todo.','Necesito un médico.','Estoy hecho polvo.'],SAD=['Esto no tiene arreglo.','Ya no puedo más.','Quiero irme de aquí.'],HAPPY=['Hoy me siento bien.','Vamos a salir adelante.','Esto empieza a funcionar.'],NIGHT=['Tengo sueño.','Qué frío hace de noche.','Hay que descansar.'],RAIN=['Menuda lluvia.','Se cuela por todas partes.'];
function say(p){const tt=S.dayT/600,r=Math.random();
 if((p.hunger??100)<35&&r<.6)return{t:pick(HUNGRY),c:'#d9a441'};if((p.thirst??100)<35&&r<.6)return{t:pick(THIRSTY),c:'#4aa3d9'};
 if(p.hp<(typeof mhp==='function'?mhp(p)*.45:45)&&r<.6)return{t:pick(HURT),c:'#d9534a'};
 if(p.mor<30&&r<.6)return{t:pick(SAD),c:'#8a8f99'};
 if((tt>.8||tt<.05)&&r<.45)return{t:pick(NIGHT),c:'#7a86c9'};
 if(((S.adv&&S.adv.weather)||0)===2&&r<.3)return{t:pick(RAIN),c:'#4aa3d9'};
 if(p.job&&PRO[p.prof]&&r<.55)return{t:pick(PRO[p.prof]),c:'#e0b04a'};
 if(p.mor>75&&r<.5)return{t:pick(HAPPY),c:'#6fc46f'};
 return{t:pick(GEN),c:'#cfd3d8'}}
/* balbuceo de voz (muestras originales CC0), una voz por tipo de aldeano */
const VB={"h0": "", "h1": "", "h2": "", "h3": "", "m0": "", "m1": "", "m2": "", "m3": "", "n0": "", "n1": "", "n2": "", "n3": ""},VBUF={};
function decVoices(){Object.keys(VB).forEach(k=>{try{const bin=atob(VB[k]),u=new Uint8Array(bin.length);for(let i=0;i<bin.length;i++)u[i]=bin.charCodeAt(i);const oc=new(window.OfflineAudioContext||window.webkitOfflineAudioContext)(1,1,32000),pr=oc.decodeAudioData(u.buffer,x=>{VBUF[k]=x},()=>{});if(pr&&pr.catch)pr.catch(()=>{})}catch(e){}})}
setTimeout(decVoices,600);
function mur(p,txt){try{if(!SND||typeof AC==='undefined'||!AC)return;const ac=AC,kind=p.age<18?'n':p.sex==='F'?'m':'h',k=kind+Math.floor(Math.random()*4),b=VBUF[k];if(!b)return;
 const s=ac.createBufferSource(),g=ac.createGain();s.buffer=b;s.playbackRate.value=(p.age>=55?.9:1)*(.94+((p.id||1)%7)*.02+Math.random()*.06);g.gain.value=Math.min(1,(typeof sfxVol==='number'?sfxVol:.6)*.9);s.connect(g);g.connect(ac.destination);s.start()}catch(e){}}
const B=new Map();let lastS=0;
function wrap(c,t,max){const w=t.split(' '),L=[];let l='';w.forEach(x=>{const n=l?l+' '+x:x;if(c.measureText(n).width>max&&l){L.push(l);l=x}else l=n});if(l)L.push(l);return L}
function draw(){
 const c=window.g;if(!c||typeof S==='undefined'||!S||!S.ppl||cam.z<ZOOM){B.clear();return}
 try{if(titleOpen()||horde||S.over)return}catch(e){}
 const pan=document.getElementById('pan');if(pan&&pan.offsetHeight>0)return;
 const now=performance.now()/1000,W=vw()/cam.z,H=vh()/cam.z,cx=cam.x+W/2,cy=cam.y+H/2,inU=new Set(U.map(u=>u.p));
 const vp=S.ppl.filter(p=>!p.away&&!p.inside&&!p.tw&&!(p.age<6)&&!inU.has(p)&&p.hp>0&&vis(p.x,p.y,-10));
 // nuevos globos
 if(B.size<MAXB&&now-lastS>1.4){const c2=vp.filter(p=>!B.has(p.id)&&now>(p._bn||0)).sort((a,b)=>{const qa=P(a.x,a.y),qb=P(b.x,b.y);return Math.hypot(qa[0]-cx,qa[1]-cy)-Math.hypot(qb[0]-cx,qb[1]-cy)}).slice(0,6);
  if(c2.length&&Math.random()<.12){const p=pick(c2),s=say(p);B.set(p.id,{p,t:s.t,col:s.c,t0:now,d:2.6+s.t.length*.055});p._bn=now+9+Math.random()*14;lastS=now;mur(p,s.t)}}
 const dpr_=typeof dpr==='number'?dpr:1;c.save();c.setTransform(cam.z*dpr_,0,0,cam.z*dpr_,-cam.x*cam.z*dpr_,-cam.y*cam.z*dpr_);
 c.font='bold 8px system-ui,sans-serif';c.textAlign='center';c.textBaseline='middle';
 B.forEach((b,id)=>{const a=now-b.t0;if(a>b.d||!vp.includes(b.p)){B.delete(id);return}
  const q=P(b.p.x,b.p.y),k=Math.min(1,a/.18),o=a>b.d-.35?(b.d-a)/.35:1,sc=.6+.4*(1-Math.pow(1-k,3)),L=wrap(c,b.t,86),w=Math.max(...L.map(l=>c.measureText(l).width))+10,h=L.length*10+6,x=q[0],y=q[1]-52-Math.sin(a*2)*.8;
  c.save();c.globalAlpha=o;c.translate(x,y);c.scale(sc,sc);
  c.fillStyle='rgba(18,20,22,.9)';c.strokeStyle=b.col;c.lineWidth=1.2;c.beginPath();const r=5;c.moveTo(-w/2+r,-h/2);c.lineTo(w/2-r,-h/2);c.quadraticCurveTo(w/2,-h/2,w/2,-h/2+r);c.lineTo(w/2,h/2-r);c.quadraticCurveTo(w/2,h/2,w/2-r,h/2);c.lineTo(4,h/2);c.lineTo(0,h/2+5);c.lineTo(-4,h/2);c.lineTo(-w/2+r,h/2);c.quadraticCurveTo(-w/2,h/2,-w/2,h/2-r);c.lineTo(-w/2,-h/2+r);c.quadraticCurveTo(-w/2,-h/2,-w/2+r,-h/2);c.closePath();c.fill();c.stroke();
  c.fillStyle='#f2efe6';L.forEach((l,i)=>c.fillText(l,0,-h/2+8+i*10));c.restore()});
 c.restore()}
const oR=window.render;if(typeof oR==='function')window.render=function(){const r=oR.apply(this,arguments);try{draw()}catch(e){}return r};
})();
